/**
 * Deeply merges source objects into the target object.
 * Handles nested objects, but arrays are not handled (replaced).
 */
export declare function deepAssign<T, U>(target: T, s: U): T & U;
export declare function deepAssign<T, U, V>(target: T, s1: U, s2: V): T & U & V;
export declare function deepAssign<T, U, V, W>(target: T, s1: U, s2: V, s3: W): T & U & V & W;
